rows=open('maze.txt').read().splitlines()
R=len(rows); C=len(rows[0])
print('R',R,'C',C)
for i,row in enumerate(rows):
    assert len(row)==C, (i,len(row))
print('all rows length', C)
# BFS from start
start=next((i,j) for i,row in enumerate(rows) for j,ch in enumerate(row) if ch=='@')
end=next((i,j) for i,row in enumerate(rows) for j,ch in enumerate(row) if ch=='E')
from collections import deque
def bfs(s):
    q=deque([s]); seen={s}
    while q:
        r,c=q.popleft()
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and rows[nr][nc]!='#' and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    return seen
s1=bfs(start); s2=bfs(end)
print('start region size', len(s1), 'end region size', len(s2))
print('overlap', len(s1 & s2))
print('end in start region', end in s1)
print('start in end region', start in s2)
""}

