            prev[(nr,nc)]=(r,c,dn); q.append((nr,nc))
if end in prev:
    path=[]; cur=end
    while prev[cur] is not None:
        r,c,dn=prev[cur]; path.append(dn); cur=(r,c)
    path.reverse()
    print('PATH FOUND', len(path))
    print(' '.join(path))
else:
    print('NO PATH')
    # closest reachable cell to end
    best=None; bd=10**9
    for (r,c) in prev:
