rows=[list(l) for l in open('maze.txt').read().splitlines()]
R=len(rows); C=len(rows[0])
start=next((i,j) for i,row in enumerate(rows) for j,ch in enumerate(row) if ch=='@')
end=next((i,j) for i,row in enumerate(rows) for j,ch in enumerate(row) if ch=='E')
print('start',start,'end',end)
# connected components
from collections import deque
comp={}
cid=0
for i in range(R):
    for j in range(C):
        if rows[i][j]!='#' and (i,j) not in comp:
            cid+=1
            q=deque([(i,j)]); comp[(i,j)]=cid
            while q:
                r,c=q.popleft()
                for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr,nc=r+dr,c+dc
                    if 0<=nr<R and 0<=nc<C and rows[nr][nc]!='#' and (nr,nc) not in comp:
                        comp[(nr,nc)]=cid; q.append((nr,nc))
print('num components', cid)
print('start comp', comp[start], 'end comp', comp[end])
print('connected?', comp[start]==comp[end])
""}

