start=next((i,j) for i,row in enumerate(rows) for j,ch in enumerate(row) if ch=='@')
end=next((i,j) for i,row in enumerate(rows) for j,ch in enumerate(row) if ch=='E')
from collections import deque
q=deque([start]); seen={start}
while q:
    r,c=q.popleft()
    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr,nc=r+dr,c+dc
        if 0<=nr<R and 0<=nc<C and rows[nr][nc]!='#' and (nr,nc) not in seen:
            seen.add((nr,nc)); q.append((nr,nc))
# find reachable cells adjacent (diagonal or straight) to end region
q2=deque([end]); seen2={end}
while q2:
    r,c=q2.popleft()
    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr,nc=r+dr,c+dc
        if 0<=nr<R and 0<=nc<C and rows[nr][nc]!='#' and (nr,nc) not in seen2:
            seen2.add((nr,nc)); q2.append((nr,nc))
# find pairs of cells (one in each region) that are adjacent (including diagonal)
pairs=[]
for a in seen:
    for b in seen2:
        if max(abs(a[0]-b[0]), abs(a[1]-b[1]))==1:
            pairs.append((a,b))
print('adjacent pairs (incl diagonal):', len(pairs))
for p in pairs[:50]:
    print(p)
