# is adjacent to BOTH components (i.e., a single wall cell that if removed would connect them).
from collections import deque
grid = [list(line.rstrip('\n')) for line in open('maze.txt')]
R, C = len(grid), len(grid[0])
start = end = None
for i in range(R):
    for j in range(C):
        if grid[i][j] == '@': start = (i,j)
        if grid[i][j] == 'E': end = (i,j)

def comp(s):
    seen={s}; q=deque([s])
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and grid[nr][nc]!='#' and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    return seen

A = comp(start); B = comp(end)
print("A size", len(A), "B size", len(B))

# For each wall cell, check adjacency to A and B
bridges = []
for r in range(R):
    for c in range(C):
        if grid[r][c] == '#':
            adjA = any((r+dr,c+dc) in A for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<R and 0<=c+dc<C)
            adjB = any((r+dr,c+dc) in B for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<R and 0<=c+dc<C)
            if adjA and adjB:
                bridges.append((r,c))
print("wall cells adjacent to both components:", bridges)
